-- Evidence and topic version ledger.
--
-- Portability rules held from the first migration, so a move to a distributed
-- PostgreSQL-compatible engine stays a configuration change rather than a
-- rewrite:
--
--   * every table carries project_id, the intended shard key;
--   * primary keys are UUIDs generated by the application, never SERIAL, since
--     a monotonic sequence is a coordination point under sharding;
--   * only the portable SQL subset is used, and no extension is required.

CREATE TABLE projects (
    id         UUID        PRIMARY KEY,
    name       TEXT        NOT NULL UNIQUE,
    created_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE sources (
    id         UUID        PRIMARY KEY,
    project_id UUID        NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    kind       TEXT        NOT NULL,
    -- Re-ingesting the same locator appends a version rather than forking a
    -- second source, which is what keeps a file's history in one chain.
    locator    TEXT        NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    UNIQUE (project_id, locator)
);

-- Evidence. Written before the sensory filter runs and never rewritten, so a
-- filtering mistake stays recoverable and nothing here is lossy.
CREATE TABLE source_versions (
    id              UUID        PRIMARY KEY,
    project_id      UUID        NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    source_id       UUID        NOT NULL REFERENCES sources (id) ON DELETE CASCADE,
    version         INTEGER     NOT NULL,
    -- Verbatim, in whatever language it arrived in. Never translated.
    content         TEXT        NOT NULL,
    content_hash    TEXT        NOT NULL,
    -- The filter gates promotion to the retrieval surface, not persistence, so
    -- its decision is a column on a row that exists either way.
    filter_decision TEXT        NOT NULL,
    filter_reason   TEXT        NOT NULL,
    recorded_at     TIMESTAMPTZ NOT NULL,
    UNIQUE (source_id, version),
    CONSTRAINT source_versions_filter_decision_known
        CHECK (filter_decision IN ('promoted', 'filtered'))
);

CREATE INDEX source_versions_by_source
    ON source_versions (project_id, source_id, version DESC);

-- The unit a retrieval hit cites.
CREATE TABLE source_spans (
    id                  UUID    PRIMARY KEY,
    project_id          UUID    NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    source_version_id   UUID    NOT NULL REFERENCES source_versions (id) ON DELETE CASCADE,
    byte_start          INTEGER NOT NULL,
    byte_end            INTEGER NOT NULL,
    -- Detected per span rather than per deployment: one source can mix
    -- languages, and the tokenizer choice follows the span.
    detected_language   TEXT,
    language_confidence REAL,
    CONSTRAINT source_spans_range_ordered CHECK (byte_end >= byte_start)
);

CREATE INDEX source_spans_by_version ON source_spans (project_id, source_version_id);

CREATE TABLE topics (
    id         UUID        PRIMARY KEY,
    project_id UUID        NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    name       TEXT        NOT NULL,
    path       TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    UNIQUE (project_id, name)
);

-- Topic history. Rows are immutable; a change appends a version.
CREATE TABLE topic_states (
    id               UUID        PRIMARY KEY,
    project_id       UUID        NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    topic_id         UUID        NOT NULL REFERENCES topics (id) ON DELETE CASCADE,
    -- Monotonic per topic. Gaps are expected: soft deletes do not renumber the
    -- versions that survive.
    version          INTEGER     NOT NULL,
    content          TEXT        NOT NULL,
    source_span_id   UUID        NOT NULL REFERENCES source_spans (id),
    -- observed_at is when the source says it happened; recorded_at is when we
    -- learned it. valid_from and valid_to are the asserted truth interval,
    -- which is independent of both.
    observed_at      TIMESTAMPTZ NOT NULL,
    recorded_at      TIMESTAMPTZ NOT NULL,
    valid_from       TIMESTAMPTZ,
    valid_to         TIMESTAMPTZ,
    supersedes       UUID        REFERENCES topic_states (id),
    -- Soft delete. Removes a state from the default retrieval surface while
    -- leaving it reachable for audit and historical traversal.
    deleted_at       TIMESTAMPTZ,
    importance       REAL        NOT NULL DEFAULT 0,
    worth_positive   INTEGER     NOT NULL DEFAULT 0,
    worth_negative   INTEGER     NOT NULL DEFAULT 0,
    access_count     INTEGER     NOT NULL DEFAULT 0,
    last_accessed_at TIMESTAMPTZ,
    UNIQUE (topic_id, version)
);

-- Latest is computed from this index, not stored in a flag. A stored flag needs
-- transactional maintenance on every insert and every soft delete, and one
-- missed path leaves two rows claiming to be current.
CREATE INDEX topic_states_latest
    ON topic_states (topic_id, version DESC)
    WHERE deleted_at IS NULL;

-- Cascade outbox. Claimed with FOR UPDATE SKIP LOCKED so several workers can
-- drain it without blocking each other on the same row.
CREATE TABLE index_jobs (
    id              UUID        PRIMARY KEY,
    project_id      UUID        NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    job_type        TEXT        NOT NULL,
    payload         JSONB       NOT NULL,
    -- Delivery is at-least-once, so a retried job must not produce a second
    -- topic state. This key is what makes reprocessing harmless.
    idempotency_key TEXT        NOT NULL UNIQUE,
    attempts        INTEGER     NOT NULL DEFAULT 0,
    available_at    TIMESTAMPTZ NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL,
    completed_at    TIMESTAMPTZ
);

CREATE INDEX index_jobs_claimable
    ON index_jobs (project_id, available_at)
    WHERE completed_at IS NULL;
